input.command:
firecrawl scrape "https://chromewebstore.google.com/search/tab%20manager?itemTypes=EXTENSION" >/dev/null && firecrawl interact --timeout 120 -o .firecrawl/links.txt --code '
for (let i=0;i<15;i++){ const b=page.getByRole("button",{name:"Load more"}); if(!(await b.count())) break; await b.first().click(); await page.waitForTimeout(1500);}
const hrefs=await page.$$eval("a[href*=\"/detail/\"]",as=>[...new Set(as.map(a=>a.href))]);
console.log(hrefs.length+"\n"+hrefs.join("\n"));
'; wc -l .firecrawl/links.txt; head -5 .firecrawl/links.txt

